try:
    print('>>> f = divmod')
    print('>>> x = 1j')
    print('>>> y = []')
    print('>>> f(x, y)')
    f = divmod
    x = 1j
    y = []
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
